    if px_all is None:
        return zeros
    try:
        if px_all.shape[0] < 260 or px_all.shape[1] == 0:
            return zeros
        idx = px_all.index
    except Exception:
        return zeros

    ref_pos = _last_rebalance_pos(idx)
    if ref_pos < 252:
        return zeros
